from decimal import Decimal, ROUND_HALF_UP
from money import amount
def quote(items, tax_rate):
    subtotal = sum((amount(i["price"]) * i["quantity"] for i in items), Decimal(0))
    return str((subtotal * (1 + amount(tax_rate))).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
